def alphaOf (sig : List Nat) (old new : Statics) : List Nat :=
  (rootIdx (old.map (·.1))).map fun i => (rootIdx (new.map (·.1))).idxOf ((sig[i]?).getD i)

def RAB : Ren := ⟨sigAB, alphaOf sigAB stA stB⟩
def RAC : Ren := ⟨sigAC, alphaOf sigAC stA stC⟩

def d0 : KD := { shared := [3, 8, 11], pinned := [], done := [0, 1, 2],
  dealloc := [10, 12, 13, 14, 16, 17], compat := [(10, 0), (12, 0), (13, 0), (14, 0), (16, 0), (17, 0)],
  dd := [([3], [4]), ([3, 4], [2])], satBan := [2], satBound := 30 }

def d1 : KD := { d0 with pinned := [11, 3], satBound := 20 }

